import pandas as pd,numpy as np
from scipy import stats
s=pd.read_csv('/app/dataset/stations.csv').set_index('station_id');r=pd.read_csv('/app/dataset/readings.csv',parse_dates=['timestamp']);s['p']=r.groupby('station_id').pollutant.first();y=r.pivot(index='timestamp',columns='station_id',values='current_reading');x=y.interpolate(method='time',limit=2,limit_direction='both')/s.p.map({'PM25':1.,'PM10':1.6});xc=x-x.mean()
# Daily intercept and trend controls, then calculate improvement fitting lagged district peers
rows=[]
for sid in s.index:
 peers=s.index[(s.district==s.loc[sid,'district'])&(s.index!=sid)&(s.index!='ST040')]
 z=xc[peers].mean(axis=1).values
 v=x[sid].values
 for mode in ['interp','observed']:
  mask=np.ones(24,dtype=bool) if mode=='interp' else y[sid].notna().values
  for control in ['linear','daily','none']:
   if control=='linear':D=np.column_stack([np.ones(24),np.arange(24)])
   elif control=='daily':D=np.eye(4)[np.arange(24)//6]
   else:D=np.ones((24,1))
   vr=v[mask]-D[mask]@np.linalg.lstsq(D[mask],v[mask],rcond=None)[0]
   corrs={}
   for lag in range(-3,4):
    zz=np.roll(z.reshape(4,6),lag,axis=1).ravel()
    zr=zz[mask]-D[mask]@np.linalg.lstsq(D[mask],zz[mask],rcond=None)[0]
    corrs[lag]=np.corrcoef(vr,zr)[0,1]
   best=max(corrs,key=corrs.get)
   rows.append({'id':sid,'mode':mode,'control':control,'corr':corrs[0],'lag':best,'best':corrs[best],'gain':corrs[best]-corrs[0]})
a=pd.DataFrame(rows);a.to_csv('/app/audit/rhythm_metrics.csv',index=False)
for control in ['daily','linear','none']:
 for mode in ['interp','observed']:
  print('\n',mode,control,'\n',a[(a.control==control)&(a['mode']==mode)].sort_values('gain',ascending=False).head(20).round(3).to_string(index=False))
print('\nMean hour by district (normalized centered)')
for d in s.district.unique():
 print(d,xc[s.index[(s.district==d)&(s.index!='ST040')]].mean(axis=1).groupby(x.index.hour).mean().round(2).to_dict())
print('\nCandidate mean hour:')
for sid in ['ST005','ST012','ST014','ST018','ST038','ST051','ST058','ST060','ST066','ST086','ST090']:
 print(sid,xc[sid].groupby(x.index.hour).mean().round(2).to_dict())
